export const portfolioTotal = portfolio.reduce((n, c) => n + c.photos.length, 0);

/**
 * แปลงเส้นทางไฟล์เต็มความละเอียดเป็นเส้นทางภาพย่อของหน้าผลงาน
 *
 * ภาพย่อสร้างไว้ล่วงหน้าด้วย scripts/make-thumbs.py เป็น WebP 480×480
 * เหตุผลที่ต้องมีอยู่ในหัวสคริปต์นั้น สรุปสั้น ๆ คือกริดแสดงภาพแค่ราว 235 พิกเซล
 * แต่เดิมต้องโหลดไฟล์เต็มหน้าละ 96 ไฟล์ รวมเกือบ 14 MB
 *
 * ใช้กับกริดของหน้าผลงานเท่านั้น ห้ามใช้กับ og:image หรือ contentUrl ใน schema
 * เพราะสองที่นั้นต้องเป็นไฟล์เต็มความละเอียด
 *
 * ถ้าเพิ่มรูปใหม่แล้วลืมรันสคริปต์ scripts/check-thumbs.mjs จะทำให้ build ไม่ผ่าน
 * ดีกว่าปล่อยขึ้นเว็บแล้วกลายเป็นช่องว่าง
 */
export function thumbOf(src: string) {
  return `/work/thumb/${src.split("/").pop()!.replace(/\.[^.]+$/, "")}.webp`;
}

/**
 * ภาพหลักของแต่ละหน้า กำหนดเองทีละหน้า ห้ามใช้สูตรสุ่ม index จาก gallery
 * เคยใช้สูตรแล้วได้ภาพคาปาซิเตอร์ไปขึ้นหัวหน้า PM2.5 ซึ่งไม่เกี่ยวกับเรื่องฝุ่นเลย
 * เวลาเพิ่มรูปชุดใหม่ ต้องกลับมาตรวจว่าภาพยังตรงกับหัวข้อของหน้าอยู่หรือไม่
 */
